// =============================================================================
// MAP TEST SUPPORT: the seeded sample fixtures and small builders
// =============================================================================
//
// The `sample_*.json` fixtures are generated by tests/fixtures/gen_sample.ts from
// seeded clusters, so every number a map test asserts on them is reproducible.
// Live captures (tests/fixtures/v1/live/<backend>/sample*.json) are preferred
// when present; the provisional ones stay the default for unit tests.
// =============================================================================

import fs from 'node:fs';
import path from 'node:path';
import type { IKnnBlock, ISampleModel, ISampleResult } from '../../src/contract/types';

const PROVISIONAL = path.resolve(__dirname, '..', 'fixtures', 'provisional');

/** The sample fixtures by file name. */
export type SampleFixture = 'sample_demo_1000.json' | 'sample_light_5000.json' | 'sample_biased_refilled.json' | 'sample_native_knn.json';

const cache = new Map<string, ISampleResult>();

/**
 * Load a sample fixture (parsed once per process, then deep-frozen so a test cannot mutate it for another).
 *
 * @param name - The fixture file.
 * @returns The `sample` answer.
 */
export function loadSample(name: SampleFixture): ISampleResult {
	const hit = cache.get(name);
	if (hit) return hit;
	const parsed = JSON.parse(fs.readFileSync(path.join(PROVISIONAL, name), 'utf8')) as ISampleResult;
	const frozen = deepFreeze(parsed);
	cache.set(name, frozen);
	return frozen;
}

/**
 * Wrap a sample answer as the map holds it.
 *
 * @param result - The answer.
 * @param extra - Overrides.
 * @returns The model.
 */
export function modelOf(result: ISampleResult, extra: Partial<ISampleModel> = {}): ISampleModel {
	return { sampleId: result.sample_id, seed: 7, mode: result.mode, receivedAt: 0, result, pinned: [], removed: [], ...extra };
}

/**
 * The PCA coordinates of a sample, interleaved x,y.
 *
 * @param result - The answer.
 * @returns n*2 floats.
 */
export function pcaXY(result: ISampleResult): Float32Array {
	const out = new Float32Array(result.n * 2);
	for (let i = 0; i < result.n; i += 1) {
		out[2 * i] = result.points.x[i] as number;
		out[2 * i + 1] = result.points.y[i] as number;
	}
	return out;
}

/**
 * A kNN block from adjacency rows.
 *
 * @param rows - Neighbour indices per point, nearest first.
 * @returns The block (sims fall by rank).
 */
export function knnFromRows(rows: number[][]): IKnnBlock {
	const offsets = [0];
	const cols: number[] = [];
	const sims: number[] = [];
	for (const row of rows) {
		row.forEach((j, r) => {
			cols.push(j);
			sims.push(1 - r * 0.05);
		});
		offsets.push(cols.length);
	}
	return { k: Math.max(0, ...rows.map((r) => r.length)), offsets_row: offsets, cols, sims };
}

/**
 * Freeze an object graph.
 *
 * @param value - Any JSON value.
 * @returns The same value, frozen.
 */
export function deepFreeze<T>(value: T): T {
	if (value && typeof value === 'object') {
		Object.freeze(value);
		for (const child of Object.values(value as Record<string, unknown>)) deepFreeze(child);
	}
	return value;
}
